// Generate a slug→category lookup from imageMap.ts so the image retriever can
// scope matches to the grounded fact's science domain (no word-association
// cross-domain mismatches). Category = the assets-png/<category>/ folder.
// Run: node scripts/gen-image-category.mjs
import { readFileSync, writeFileSync } from 'node:fs';
const src = readFileSync('src/generated/imageMap.ts', 'utf8');
const re = /"([^"]+)":\s*require\("[^"]*assets-png\/([a-z-]+)\//g;
const out = {};
let m;
while ((m = re.exec(src))) out[m[1]] = m[2];
const body =
  '// AUTO-GENERATED by scripts/gen-image-category.mjs — do not edit.\n' +
  '// slug → image catalog category (folder), for domain-scoped image retrieval.\n' +
  '/* eslint-disable */\n' +
  'export const IMAGE_CATEGORY: Record<string, string> = ' +
  JSON.stringify(out) +
  ';\n';
writeFileSync('src/generated/imageCategory.generated.ts', body);
const counts = {};
for (const c of Object.values(out)) counts[c] = (counts[c] || 0) + 1;
console.log(Object.keys(out).length, 'images categorized:', counts);
